import pandas as pd
import matplotlib.pyplot as plt
from sklearn.cluster import KMeans
from sklearn.decomposition import PCA
from sklearn.metrics import adjusted_rand_score
from sklearn.preprocessing import StandardScaler

# This code was generated by Claude

features = ['valence', 'tempo', 'energy', 'danceability', 'instrumentalness']

tracks_df = pd.read_csv('dataset.csv').dropna(subset=features).reset_index(drop=True)
X = StandardScaler().fit_transform(tracks_df[features])

# PCA to reduce the dimensionality of the data for visualization
pca = PCA(n_components=2, random_state=42)
X2 = pca.fit_transform(X)
print("PCA explained variance:", pca.explained_variance_ratio_.round(3))
print(pd.DataFrame(pca.components_, columns=features, index=['PC1', 'PC2']).round(2))

fig, axes = plt.subplots(1, 2, figsize=(14, 6))
sample = tracks_df.sample(8000, random_state=42).index

for ax, k in zip(axes, [4, 5]):
    km = KMeans(n_clusters=k, n_init=10, random_state=42).fit(X)
    tracks_df[f'cluster_k{k}'] = km.labels_

    # 1) Cluster sizes and means
    print(f"\n=== k={k}: cluster sizes ===")
    print(tracks_df[f'cluster_k{k}'].value_counts().sort_index())
    print(f"\n=== k={k}: cluster means (original scale) ===")
    print(tracks_df.groupby(f'cluster_k{k}')[features].mean().round(3))

    # 2) Stability: how similar the clustering is with different seeds (1.0 = identical)
    aris = []
    for seed in [1, 2, 3, 4, 5]:
        other = KMeans(n_clusters=k, n_init=10, random_state=seed).fit(X).labels_
        aris.append(adjusted_rand_score(km.labels_, other))
    print(f"k={k} stability (ARI, average): {sum(aris) / len(aris):.3f}")

    # 3) PCA plot
    sc = ax.scatter(X2[sample, 0], X2[sample, 1], c=km.labels_[sample],
                    cmap='tab10', s=6, alpha=0.6)
    ax.set(title=f'K-means k={k} (PCA 2D)',
           xlabel=f'PC1 ({pca.explained_variance_ratio_[0]:.0%})',
           ylabel=f'PC2 ({pca.explained_variance_ratio_[1]:.0%})')
    ax.legend(*sc.legend_elements(), title='Clusters', loc='best')

plt.tight_layout()
plt.savefig('clusters_pca.png', dpi=150)